-- Parity test for Cognos report Bill_Dispute_Log (cluster BIL_008, 6 runs/day)
-- Generated by SemanticLift 1.0.0; tolerance +/-0.5% on totals
WITH cognos AS (
    SELECT billing.PAYMENT_STATUS AS payment_status, dt.FULL_DATE AS full_date, customer.CUSTOMER_NAME AS customer_name, customer.CUSTOMER_SEGMENT AS customer_segment, location.REGION AS region, SUM(billing.BILL_AMOUNT) AS total_bill_amount
    FROM CORE.FCT_BILLING billing
    JOIN CORE.DIM_DATE dt ON billing.DATE_KEY = dt.DATE_KEY
    JOIN CORE.DIM_METER meter ON billing.METER_ID = meter.METER_ID
    JOIN CORE.DIM_CUSTOMER customer ON meter.CUSTOMER_ID = customer.CUSTOMER_ID
    JOIN CORE.DIM_LOCATION location ON meter.LOCATION_ID = location.LOCATION_ID
    WHERE dt.FISCAL_YEAR = 2026
    GROUP BY 1, 2, 3, 4, 5
),
semantic AS (
    SELECT * FROM SEMANTIC_VIEW(
        SEM.SV_BILLING_REVENUE
        DIMENSIONS billing.payment_status, dt.full_date, customer.customer_name, customer.customer_segment, location.region
        METRICS billing.total_bill_amount
    ) WHERE fiscal_year = 2026
)
SELECT
    (SELECT COUNT(*) FROM cognos) AS cognos_rows,
    (SELECT COUNT(*) FROM semantic) AS semantic_rows,
    SUM(c.total_bill_amount) AS cognos_total_bill_amount, SUM(s.total_bill_amount) AS semantic_total_bill_amount,
    IFF(ABS(COALESCE(SUM(s.total_bill_amount), 0) - COALESCE(SUM(c.total_bill_amount), 0)) <= 0.5 / 100 * ABS(NULLIF(SUM(c.total_bill_amount), 0)), 'PASS', 'FAIL') AS status_total_bill_amount
FROM cognos c
FULL OUTER JOIN semantic s ON c.payment_status IS NOT DISTINCT FROM s.payment_status AND c.full_date IS NOT DISTINCT FROM s.full_date AND c.customer_name IS NOT DISTINCT FROM s.customer_name AND c.customer_segment IS NOT DISTINCT FROM s.customer_segment AND c.region IS NOT DISTINCT FROM s.region;
